test('Drag and Drop Upload', async ({ page }) => {
  const buffer = Buffer.from('foo,bar\n1,2');
  const dataTransfer = await page.evaluateHandle((buf) => {
    const dt = new DataTransfer();
    const file = new File([buf], 'data.csv', { type: 'text/csv' });
    dt.items.add(file);
    return dt;
  }, buffer);
  await page.dispatchEvent('.dropzone', 'drop', { dataTransfer });
});

