test('Fail safely', async ({ page }) => {
  await expect.soft(page.locator('.flaky')).toBeVisible();
  if (test.info().errors.length > 0) return;
  await page.click('.next-step');
});

test.afterEach(async ({ page }, testInfo) => {
  if (testInfo.status !== testInfo.expectedStatus) {
    const softErrors = testInfo.errors.filter(e => e.message.includes('Soft'));
    await sendToSlack(softErrors);
  }
});

